import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"多跳检索","description":"","frontmatter":{"title":"多跳检索","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multi-hop-retrieval.md","filePath":"llm/multi-hop-retrieval.md","lastUpdated":1789023840000}'),A={name:"llm/multi-hop-retrieval.md"};function m(E,a,_,c,u,f){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="多跳检索" tabindex="-1">多跳检索 <a class="header-anchor" href="#多跳检索" aria-label="Permalink to &quot;多跳检索&quot;">​</a></h1><div class="epigraph"><p>答案不在单段里。第一跳找到桥接实体，第二跳才拿到事实。单次 Top-k 只会返回与问句表面相近的段。</p><footer>—— 对照 HotpotQA 的多跳设定；IRCoT 把检索写进推理循环</footer></div><p><a href="/llm/query-rewrite-hyde">上一课</a>优化单跳查询。有的问题必须组合两段证据（「导演的出生城市的市长是谁」）。本课写多跳检索。缺口是迭代：下一查询由上一轮阅读决定。后课引用默认：多跳更容易张冠李戴，归因必须按跳检查。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单跳检索最大化与问句的表面相关，桥接段可能不含问句里的词。Yang 等 HotpotQA 把这类题做成基准。策略：先检索，读出中间实体或子问题，再检索。IRCoT 一类把思维链与检索交错：每步生成要用的查询。失败是误差累积——第一跳错实体，后面全错——以及把多跳做成「把 k 加到 50」的假多跳。</p><p>与<a href="/llm/long-context-vs-rag">长上下文是否取代 RAG</a> 的关系：窗口能放下多段时，仍要<strong>选对段</strong>；只靠更长窗口会把桥接淹没在相似噪声里。</p><p><span class="marginnote">多跳次数应有上限。无限循环会把延迟与幻觉查询写成「更努力的检索」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：最大跳数、每跳 \\(k\\)、停止条件（阅读器声称可答或证据不足）。查询生成必须条件于已检索块，避免重复同一查询。评测：支持事实是否都在证据链上（HotpotQA 的 supporting facts），不只看最终答案——最终答案可猜对。图检索（实体链）是结构先验，与纯向量迭代互补，见主干 GraphRAG 一类工作，本课不重写。</p>',9)),(e(),s(h,null,{default:o(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q0%5B%22%E5%8E%9F%E9%97%AE%E9%A2%98%22%5D%20--%3E%20R1%5B%22%E7%AC%AC%201%20%E8%B7%B3%E6%A3%80%E7%B4%A2%22%5D%0A%20%20R1%20--%3E%20READ%5B%22%E9%98%85%E8%AF%BB%20%2F%20%E5%AD%90%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20READ%20--%3E%20R2%5B%22%E7%AC%AC%202%20%E8%B7%B3%E6%A3%80%E7%B4%A2%22%5D%0A%20%20R2%20--%3E%20ANS%5B%22%E4%BD%9C%E7%AD%94%E6%88%96%E5%81%9C%E6%AD%A2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每跳更新的是查询条件分布。阅读器从块中抽出桥接词，相当于把隐变量实例化再查询。这比一次性改写更强，因为桥接词往往不在用户问句里。代价是把阅读器错误写进下一查询。因此中间步应保守：抽实体用约束解码或短抽取，而不是再生成一篇 HyDE。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两跳以上的开域问题稀疏，评测集小，易过拟合 HotpotQA 文风。下一课引用：无论几跳，读者可见的出处必须可解析。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多跳是迭代「检索–读–再查询」，不是加大 \\(k\\)。</li><li>要用支持事实评估链条，防止猜对最终答案。</li><li>跳数封顶；中间抽取宜短，避免误差放大。</li><li>出处：Yang 等 HotpotQA；Trivedi 等 IRCoT。</li></ul>',6))])}const D=l(A,[["render",m]]);export{B as __pageData,D as default};
